const BASE = '/api/v1'

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    ...options,
  })
  if (!res.ok) {
    const body = await res.json().catch(() => ({ detail: res.statusText }))
    throw new Error(body.detail || `HTTP ${res.status}`)
  }
  return res.json()
}

// --- Instances ---

export const instances = {
  list: () => request<import('../types').SdrInstance[]>('/instances'),
  get: (id: number) => request<import('../types').SdrInstance>(`/instances/${id}`),
  create: (data: { name: string; url: string; enabled?: boolean; desired_profile?: string | null }) =>
    request<import('../types').SdrInstance>('/instances', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  update: (id: number, data: Partial<{ name: string; url: string; enabled: boolean; desired_profile: string | null }>) =>
    request<import('../types').SdrInstance>(`/instances/${id}`, {
      method: 'PUT',
      body: JSON.stringify(data),
    }),
  delete: (id: number) => request<{ ok: boolean }>(`/instances/${id}`, { method: 'DELETE' }),
  start: (id: number) => request<{ ok: boolean }>(`/instances/${id}/start`, { method: 'POST' }),
  stop: (id: number) => request<{ ok: boolean }>(`/instances/${id}/stop`, { method: 'POST' }),
  status: (id: number) => request<any>(`/instances/${id}/status`),
  profiles: (id: number) => request<import('../types').AvailableProfile[]>(`/instances/${id}/profiles`),
}

// --- Targets ---

export const targets = {
  list: (instanceId?: number) =>
    request<import('../types').WatchTarget[]>(
      `/targets${instanceId != null ? `?instance_id=${instanceId}` : ''}`
    ),
  create: (data: {
    instance_id: number
    freq_hz: number
    bandwidth_hz?: number
    label?: string
    threshold_db?: number
    enabled?: boolean
  }) =>
    request<import('../types').WatchTarget>('/targets', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  update: (id: number, data: Partial<import('../types').WatchTarget>) =>
    request<import('../types').WatchTarget>(`/targets/${id}`, {
      method: 'PUT',
      body: JSON.stringify(data),
    }),
  delete: (id: number) => request<{ ok: boolean }>(`/targets/${id}`, { method: 'DELETE' }),
}

// --- Events ---

export const events = {
  list: (params?: {
    page?: number
    page_size?: number
    instance_id?: number
    freq_min?: number
    freq_max?: number
    date_from?: string
    date_to?: string
    label?: string
  }) => {
    const searchParams = new URLSearchParams()
    if (params) {
      Object.entries(params).forEach(([k, v]) => {
        if (v != null) searchParams.set(k, String(v))
      })
    }
    const qs = searchParams.toString()
    return request<import('../types').PaginatedResponse<import('../types').DetectionEvent>>(
      `/events${qs ? `?${qs}` : ''}`
    )
  },
  stats: () => request<import('../types').EventStats>('/events/stats'),
  exportCsv: () => `${BASE}/events/export`,
}

// --- Recordings ---

export const recordings = {
  list: () => request<string[]>('/recordings'),
  url: (filename: string) => `${BASE}/recordings/${encodeURIComponent(filename)}`,
  delete: (filename: string) =>
    request<{ ok: boolean }>(`/recordings/${encodeURIComponent(filename)}`, { method: 'DELETE' }),
}

// --- Notifications ---

export const notifications = {
  list: () => request<import('../types').NotificationConfig[]>('/notifications'),
  test: (backend: string) => request<{ ok: boolean }>(`/notifications/${backend}/test`, { method: 'POST' }),
}

// --- Settings ---

export const settings = {
  get: () => request<import('../types').GlobalSettings>('/settings'),
  update: (data: Partial<import('../types').GlobalSettings>) =>
    request<import('../types').GlobalSettings>('/settings', {
      method: 'PUT',
      body: JSON.stringify(data),
    }),
}

// --- Health ---

export const health = () => request<{ status: string; version: string }>('/health')

import { useState } from 'react'
import AppLayout from './components/layout/AppLayout'
import Dashboard from './components/dashboard/Dashboard'
import ConfigPage from './components/config/ConfigPage'
import HistoryPage from './components/history/HistoryPage'
import type { Page } from './types'

export default function App() {
  const [page, setPage] = useState<Page>('dashboard')

  return (
    <AppLayout currentPage={page} onNavigate={setPage}>
      {page === 'dashboard' && <Dashboard />}
      {page === 'config' && <ConfigPage />}
      {page === 'history' && <HistoryPage />}
    </AppLayout>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { health } from '../../api/client'
import Sidebar from './Sidebar'
import Header from './Header'
import type { Page } from '../../types'

interface AppLayoutProps {
  currentPage: Page
  onNavigate: (page: Page) => void
  children: React.ReactNode
}

export default function AppLayout({ currentPage, onNavigate, children }: AppLayoutProps) {
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [backendConnected, setBackendConnected] = useState(false)

  const checkHealth = useCallback(async () => {
    try {
      await health()
      setBackendConnected(true)
    } catch (_) {
      setBackendConnected(false)
    }
  }, [])

  useEffect(() => {
    checkHealth()
    const interval = setInterval(checkHealth, 10000)
    return () => clearInterval(interval)
  }, [checkHealth])

  return (
    <div className="h-screen flex overflow-hidden">
      {/* Mobile overlay */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <div className={`
        fixed inset-y-0 left-0 z-50 lg:static lg:z-auto
        transform transition-transform duration-200
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
      `}>
        <Sidebar
          currentPage={currentPage}
          onNavigate={(page) => {
            onNavigate(page)
            setSidebarOpen(false)
          }}
        />
      </div>

      {/* Main content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        <Header
          currentPage={currentPage}
          isConnected={backendConnected}
          onMenuToggle={() => setSidebarOpen(!sidebarOpen)}
        />
        <main className="flex-1 overflow-auto p-4 md:p-6">
          {children}
        </main>
      </div>
    </div>
  )
}

import { useCallback, useEffect, useRef } from 'react'

interface SpectrumDisplayProps {
  fftData: number[] | null
  centerFreq: number
  bandwidth: number
  className?: string
}

const GRID_COLOR = '#1f2937'
const SPECTRUM_COLOR = '#00ff41'
const FILL_COLOR = 'rgba(0, 255, 65, 0.08)'
const LABEL_COLOR = '#9ca3af'

/** Compute percentile value from sorted array */
function percentile(sorted: number[], p: number): number {
  const idx = (p / 100) * (sorted.length - 1)
  const lo = Math.floor(idx)
  const hi = Math.ceil(idx)
  if (lo === hi) return sorted[lo]
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo)
}

export default function SpectrumDisplay({ fftData, centerFreq, bandwidth, className = '' }: SpectrumDisplayProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const prevData = useRef<number[] | null>(null)
  // Smoothed display range for stable rendering
  const rangeRef = useRef<{ min: number; max: number } | null>(null)

  const draw = useCallback(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const rect = canvas.getBoundingClientRect()
    const dpr = window.devicePixelRatio || 1
    canvas.width = rect.width * dpr
    canvas.height = rect.height * dpr
    ctx.scale(dpr, dpr)

    const w = rect.width
    const h = rect.height
    const padding = { top: 10, right: 10, bottom: 30, left: 50 }
    const plotW = w - padding.left - padding.right
    const plotH = h - padding.top - padding.bottom

    // Clear
    ctx.fillStyle = '#0a0e17'
    ctx.fillRect(0, 0, w, h)

    // Smoothing between frames
    const data = fftData ?? prevData.current
    if (data) prevData.current = data
    if (!data || data.length === 0) return

    // Auto-scale: use percentiles to find stable display range
    const sorted = [...data].sort((a, b) => a - b)
    const p5 = percentile(sorted, 2)
    const p95 = percentile(sorted, 98)
    const margin = Math.max(Math.abs(p95 - p5) * 0.1, 10)

    const targetMin = p5 - margin
    const targetMax = p95 + margin

    // Smooth transitions (exponential moving average)
    const alpha = rangeRef.current ? 0.1 : 1.0
    if (!rangeRef.current) {
      rangeRef.current = { min: targetMin, max: targetMax }
    } else {
      rangeRef.current.min += (targetMin - rangeRef.current.min) * alpha
      rangeRef.current.max += (targetMax - rangeRef.current.max) * alpha
    }

    const valMin = rangeRef.current.min
    const valMax = rangeRef.current.max
    const valRange = valMax - valMin || 1

    // Grid lines (5 evenly spaced)
    ctx.strokeStyle = GRID_COLOR
    ctx.lineWidth = 0.5
    const gridSteps = 5
    for (let i = 0; i <= gridSteps; i++) {
      const val = valMin + (valRange / gridSteps) * i
      const y = padding.top + plotH * (1 - i / gridSteps)
      ctx.beginPath()
      ctx.moveTo(padding.left, y)
      ctx.lineTo(padding.left + plotW, y)
      ctx.stroke()

      ctx.fillStyle = LABEL_COLOR
      ctx.font = '10px monospace'
      ctx.textAlign = 'right'
      ctx.fillText(`${Math.round(val)}`, padding.left - 5, y + 3)
    }

    // Frequency labels
    const startFreq = centerFreq - bandwidth / 2
    const steps = 5
    ctx.textAlign = 'center'
    for (let i = 0; i <= steps; i++) {
      const freq = startFreq + (bandwidth / steps) * i
      const x = padding.left + (plotW / steps) * i
      ctx.fillStyle = LABEL_COLOR
      ctx.fillText(`${(freq / 1e6).toFixed(2)}`, x, h - 5)
    }

    // Draw spectrum
    ctx.beginPath()
    ctx.strokeStyle = SPECTRUM_COLOR
    ctx.lineWidth = 1.5

    const binStep = plotW / data.length
    for (let i = 0; i < data.length; i++) {
      const x = padding.left + i * binStep
      const clamped = Math.max(valMin, Math.min(valMax, data[i]))
      const y = padding.top + plotH * (1 - (clamped - valMin) / valRange)
      if (i === 0) ctx.moveTo(x, y)
      else ctx.lineTo(x, y)
    }
    ctx.stroke()

    // Fill under curve
    ctx.lineTo(padding.left + plotW, padding.top + plotH)
    ctx.lineTo(padding.left, padding.top + plotH)
    ctx.closePath()
    ctx.fillStyle = FILL_COLOR
    ctx.fill()
  }, [fftData, centerFreq, bandwidth])

  useEffect(() => {
    draw()
  }, [draw])

  useEffect(() => {
    const handleResize = () => draw()
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [draw])

  return (
    <canvas
      ref={canvasRef}
      className={`w-full rounded-lg ${className}`}
      style={{ height: '256px' }}
    />
  )
}

import { AlertTriangle } from 'lucide-react'
import { formatFreqMHz, formatDb, formatTime } from '../../utils/format'
import { UI } from '../../utils/strings'

interface LiveEvent {
  type: string
  instance_id: number
  timestamp: string
  freq_hz: number
  peak_db: number
  target_label: string
}

interface EventFeedProps {
  events: LiveEvent[]
}

export default function EventFeed({ events }: EventFeedProps) {
  if (events.length === 0) {
    return (
      <div className="text-sdr-muted text-sm py-8 text-center">
        {UI.hist_no_events}
      </div>
    )
  }

  return (
    <div className="space-y-1.5 max-h-64 overflow-auto">
      {events.map((ev, i) => (
        <div key={i} className="flex items-center gap-3 p-2 bg-sdr-bg rounded-lg border border-sdr-border/50 animate-pulse-once">
          <AlertTriangle className="w-3.5 h-3.5 text-sdr-red shrink-0" />
          <div className="flex-1 min-w-0">
            <span className="text-sm font-medium text-sdr-red">
              {ev.target_label || formatFreqMHz(ev.freq_hz)}
            </span>
            <span className="text-xs text-sdr-muted ml-2">
              {formatFreqMHz(ev.freq_hz)} &middot; {formatDb(ev.peak_db)}
            </span>
          </div>
          <span className="text-xs text-sdr-muted shrink-0">
            {formatTime(ev.timestamp)}
          </span>
        </div>
      ))}
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { Activity, Radio, AlertTriangle } from 'lucide-react'
import { instances as instancesApi } from '../../api/client'
import { useWebSocket } from '../../hooks/useWebSocket'
import { UI } from '../../utils/strings'
import SpectrumDisplay from './SpectrumDisplay'
import EventFeed from './EventFeed'
import InstanceStatusCard from './InstanceStatusCard'
import type { SdrInstance } from '../../types'

interface LiveEvent {
  type: string
  instance_id: number
  timestamp: string
  freq_hz: number
  peak_db: number
  target_label: string
}

export default function Dashboard() {
  const [instances, setInstances] = useState<SdrInstance[]>([])
  const [selectedId, setSelectedId] = useState<number | null>(null)
  const [fftData, setFftData] = useState<number[] | null>(null)
  const [liveEvents, setLiveEvents] = useState<LiveEvent[]>([])
  const [runningIds, setRunningIds] = useState<number[]>([])
  const selectedIdRef = useRef(selectedId)
  selectedIdRef.current = selectedId

  const refreshInstances = useCallback(async () => {
    const data = await instancesApi.list()
    setInstances(data)
    const running: number[] = []
    for (const inst of data) {
      try {
        const status = await instancesApi.status(inst.id)
        if (status.running) running.push(inst.id)
      } catch (_) { /* ignore */ }
    }
    setRunningIds(running)
    if (data.length > 0 && selectedIdRef.current === null) {
      setSelectedId(data[0].id)
    }
  }, [])

  useEffect(() => { refreshInstances() }, [refreshInstances])

  // Poll instance status every 3s
  useEffect(() => {
    const interval = setInterval(refreshInstances, 3000)
    return () => clearInterval(interval)
  }, [refreshInstances])

  const isSelectedRunning = selectedId != null && runningIds.includes(selectedId)

  // FFT WebSocket
  const fftUrl = selectedId ? `/ws/spectrum/${selectedId}` : '/ws/spectrum/0'
  useWebSocket({
    url: fftUrl,
    enabled: isSelectedRunning,
    onMessage: useCallback((data: number[]) => setFftData(data), []),
  })

  // Events WebSocket
  useWebSocket({
    url: '/ws/events',
    enabled: runningIds.length > 0,
    onMessage: useCallback((data: LiveEvent) => {
      setLiveEvents(prev => [data, ...prev].slice(0, 50))
    }, []),
  })

  const selected = instances.find(i => i.id === selectedId)

  const handleStartAndSelect = useCallback(async (id: number) => {
    setSelectedId(id)
    setFftData(null)
    await instancesApi.start(id)
    // Poll rapidly after start to pick up connection info
    for (let i = 0; i < 5; i++) {
      await new Promise(r => setTimeout(r, 1000))
      await refreshInstances()
    }
  }, [refreshInstances])

  const handleStop = useCallback(async (id: number) => {
    await instancesApi.stop(id)
    setFftData(null)
    await refreshInstances()
  }, [refreshInstances])

  return (
    <div className="space-y-6">
      {/* Status cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="card flex items-center gap-4">
          <div className="w-10 h-10 rounded-lg bg-sdr-cyan/10 flex items-center justify-center">
            <Radio className="w-5 h-5 text-sdr-cyan" />
          </div>
          <div>
            <p className="text-sm text-sdr-muted">{UI.dash_instances}</p>
            <p className="text-xl font-bold">{instances.length}</p>
          </div>
        </div>
        <div className="card flex items-center gap-4">
          <div className="w-10 h-10 rounded-lg bg-sdr-green/10 flex items-center justify-center">
            <Activity className="w-5 h-5 text-sdr-green" />
          </div>
          <div>
            <p className="text-sm text-sdr-muted">Aktive Monitore</p>
            <p className="text-xl font-bold">{runningIds.length}</p>
          </div>
        </div>
        <div className="card flex items-center gap-4">
          <div className="w-10 h-10 rounded-lg bg-sdr-amber/10 flex items-center justify-center">
            <AlertTriangle className="w-5 h-5 text-sdr-amber" />
          </div>
          <div>
            <p className="text-sm text-sdr-muted">{UI.dash_events}</p>
            <p className="text-xl font-bold">{liveEvents.length}</p>
          </div>
        </div>
      </div>

      {/* Instance cards */}
      {instances.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {instances.map(inst => (
            <InstanceStatusCard
              key={inst.id}
              instance={inst}
              isRunning={runningIds.includes(inst.id)}
              onStart={handleStartAndSelect}
              onStop={handleStop}
              onSelect={setSelectedId}
              selected={selectedId === inst.id}
            />
          ))}
        </div>
      )}

      {/* Spectrum */}
      <div className="card">
        <h3 className="text-sm font-medium text-sdr-muted mb-3">
          {UI.dash_spectrum}
          {selected && <span className="text-sdr-cyan ml-2">— {selected.name}</span>}
        </h3>
        {isSelectedRunning ? (
          <SpectrumDisplay
            fftData={fftData}
            centerFreq={selected?.center_freq ?? 0}
            bandwidth={selected?.bandwidth ?? 0}
          />
        ) : (
          <div className="h-64 bg-sdr-bg rounded-lg flex items-center justify-center border border-sdr-border">
            <p className="text-sdr-muted text-sm">
              {instances.length === 0 ? UI.dash_no_instances : 'Monitor starten, um Spektrum anzuzeigen.'}
            </p>
          </div>
        )}
      </div>

      {/* Live events */}
      <div className="card">
        <h3 className="text-sm font-medium text-sdr-muted mb-3">{UI.dash_events}</h3>
        <EventFeed events={liveEvents} />
      </div>
    </div>
  )
}

"""SDR instance CRUD + start/stop monitoring."""

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.ext.asyncio import AsyncSession

from .. import crud
from ..database import get_db
from ..schemas import AvailableProfile, InstanceCreate, InstanceRead, InstanceUpdate

router = APIRouter()


@router.get("/instances", response_model=list[InstanceRead])
async def list_instances(db: AsyncSession = Depends(get_db)):
    return await crud.get_instances(db)


@router.post("/instances", response_model=InstanceRead, status_code=201)
async def create_instance(data: InstanceCreate, db: AsyncSession = Depends(get_db)):
    return await crud.create_instance(db, data)


@router.get("/instances/{instance_id}", response_model=InstanceRead)
async def get_instance(instance_id: int, db: AsyncSession = Depends(get_db)):
    inst = await crud.get_instance(db, instance_id)
    if not inst:
        raise HTTPException(404, "Instanz nicht gefunden")
    return inst


@router.put("/instances/{instance_id}", response_model=InstanceRead)
async def update_instance(instance_id: int, data: InstanceUpdate, db: AsyncSession = Depends(get_db)):
    inst = await crud.update_instance(db, instance_id, data)
    if not inst:
        raise HTTPException(404, "Instanz nicht gefunden")
    return inst


@router.delete("/instances/{instance_id}")
async def delete_instance(instance_id: int, db: AsyncSession = Depends(get_db)):
    if not await crud.delete_instance(db, instance_id):
        raise HTTPException(404, "Instanz nicht gefunden")
    return {"ok": True}


@router.post("/instances/{instance_id}/start")
async def start_instance(instance_id: int, db: AsyncSession = Depends(get_db)):
    inst = await crud.get_instance(db, instance_id)
    if not inst:
        raise HTTPException(404, "Instanz nicht gefunden")
    from ..services.monitor_manager import manager
    await manager.start_instance(instance_id, db)
    return {"ok": True, "message": f"Instanz '{inst.name}' gestartet"}


@router.post("/instances/{instance_id}/stop")
async def stop_instance(instance_id: int, db: AsyncSession = Depends(get_db)):
    inst = await crud.get_instance(db, instance_id)
    if not inst:
        raise HTTPException(404, "Instanz nicht gefunden")
    from ..services.monitor_manager import manager
    await manager.stop_instance(instance_id, db)
    return {"ok": True, "message": f"Instanz '{inst.name}' gestoppt"}


@router.get("/instances/{instance_id}/status")
async def instance_status(instance_id: int, db: AsyncSession = Depends(get_db)):
    inst = await crud.get_instance(db, instance_id)
    if not inst:
        raise HTTPException(404, "Instanz nicht gefunden")
    from ..services.monitor_manager import manager
    running = manager.is_running(instance_id)
    return {
        "id": inst.id,
        "name": inst.name,
        "is_connected": inst.is_connected,
        "running": running,
        "center_freq": inst.center_freq,
        "bandwidth": inst.bandwidth,
        "fft_size": inst.fft_size,
    }


@router.get("/instances/{instance_id}/profiles", response_model=list[AvailableProfile])
async def get_profiles(instance_id: int, db: AsyncSession = Depends(get_db)):
    inst = await crud.get_instance(db, instance_id)
    if not inst:
        raise HTTPException(404, "Instanz nicht gefunden")

    from ..services.monitor_manager import fetch_profiles_from_url, manager

    # If monitor is running, try to read cached profiles first
    monitor = manager.get_monitor(instance_id)
    if monitor and monitor.available_profiles:
        return monitor.available_profiles

    # Otherwise make a temporary WebSocket connection
    profiles = await fetch_profiles_from_url(inst.url)
    return profiles

