"""JWT + bcrypt authentication utilities."""

from datetime import datetime, timedelta, timezone

from fastapi import Depends, HTTPException, Query, WebSocket, status
from fastapi.security import OAuth2PasswordBearer
from jose import JWTError, jwt
from passlib.hash import bcrypt

from .config import settings

oauth2_scheme = OAuth2PasswordBearer(tokenUrl="/api/v1/auth/login")


def verify_password(plain: str, hashed: str) -> bool:
    return bcrypt.verify(plain, hashed)


def create_access_token(subject: str) -> str:
    expire = datetime.now(timezone.utc) + timedelta(hours=settings.auth_jwt_expire_hours)
    payload = {"sub": subject, "exp": expire}
    return jwt.encode(payload, settings.auth_jwt_secret, algorithm="HS256")


async def get_current_user(token: str = Depends(oauth2_scheme)) -> str:
    try:
        payload = jwt.decode(token, settings.auth_jwt_secret, algorithms=["HS256"])
        username: str | None = payload.get("sub")
        if username is None:
            raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Ungültiger Token")
    except JWTError:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Ungültiger Token")
    return username


async def validate_ws_token(websocket: WebSocket, token: str = Query(default="")) -> str:
    """Validate token from WebSocket query parameter."""
    if not token:
        await websocket.close(code=1008)
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN)
    try:
        payload = jwt.decode(token, settings.auth_jwt_secret, algorithms=["HS256"])
        username: str | None = payload.get("sub")
        if username is None:
            await websocket.close(code=1008)
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN)
    except JWTError:
        await websocket.close(code=1008)
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN)
    return username

